$ErrorActionPreference='Stop'; $sql="SELECT current_database() AS db,(SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE') AS tables,CASE WHEN to_regclass('public.vendor') IS NULL THEN -1 ELSE (SELECT count(*) FROM vendor) END AS vendors,CASE WHEN to_regclass('public.access') IS NULL THEN -1 ELSE (SELECT count(*) FROM access) END AS access_rows,CASE WHEN to_regclass('public.retail') IS NULL THEN -1 ELSE (SELECT count(*) FROM retail) END AS retail_rows,CASE WHEN to_regclass('public.navigation_menu') IS NULL THEN -1 ELSE (SELECT count(*) FROM navigation_menu) END AS navigation_menus,CASE WHEN to_regclass('public.navigation_item') IS NULL THEN -1 ELSE (SELECT count(*) FROM navigation_item) END AS navigation_items,CASE WHEN to_regclass('public.orders') IS NULL THEN -1 ELSE (SELECT count(*) FROM orders) END AS orders,CASE WHEN to_regclass('public.payment') IS NULL THEN -1 ELSE (SELECT count(*) FROM payment) END AS payments,CASE WHEN to_regclass('public.shipping_shipment') IS NULL THEN -1 ELSE (SELECT count(*) FROM shipping_shipment) END AS shipments,CASE WHEN to_regclass('public.doctrine_migration_versions') IS NULL THEN -1 ELSE (SELECT count(*) FROM doctrine_migration_versions) END AS migrations;"; foreach($db in @('app','app_preprod')){$url=$env:DATABASE_URL -replace '/app(\?|$)',('/'+$db+'$1'); Write-Output "--- $db ---"; & psql $url -X --no-psqlrc --csv -v ON_ERROR_STOP=1 -c $sql}; Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue
